@namespace sv_39ebe269cbd34165bd1514589a11ff80.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application progress">
    <ol class="step-list">
        @for (int i = 0; i < StepNames.Count; i++)
        {
            var stepIndex = i;
            var status = GetStepStatus(stepIndex);
            <li class="step-item @status" @onclick="() => HandleStepClick(stepIndex)" role="button" aria-current="@(stepIndex == CurrentStep ? "step" : null)">
                <span class="step-badge">
                    @if (CompletedSteps.Contains(stepIndex))
                    {
                        <span class="checkmark">&#10003;</span>
                    }
                    else
                    {
                        @(stepIndex + 1)
                    }
                </span>
                <span class="step-label">@StepNames[stepIndex]</span>
            </li>
        }
    </ol>
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter, EditorRequired] public EventCallback<int> OnStepClicked { get; set; }

    private static readonly List<string> StepNames = new()
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    private string GetStepStatus(int step)
    {
        if (step == CurrentStep) return "active";
        if (CompletedSteps.Contains(step)) return "completed";
        return "dimmed";
    }

    private async Task HandleStepClick(int step)
    {
        if (CompletedSteps.Contains(step))
        {
            await OnStepClicked.InvokeAsync(step);
        }
    }
}

@namespace sv_39ebe269cbd34165bd1514589a11ff80.Components.Pages.Apply

<div class="work-entry-form">
    <div class="form-row">
        <div class="form-group">
            <label>Company Name</label>
            <input type="text" value="@Company" @onchange="e => UpdateField(() => Company = (string?)e.Value ?? string.Empty)" />
        </div>
        <div class="form-group">
            <label>Job Title</label>
            <input type="text" value="@Title" @onchange="e => UpdateField(() => Title = (string?)e.Value ?? string.Empty)" />
        </div>
    </div>
    <div class="form-row">
        <div class="form-group">
            <label>Start Date</label>
            <input type="date" value="@StartDate.ToString("yyyy-MM-dd")" @onchange="e => UpdateField(() => StartDate = DateTime.Parse((string?)e.Value ?? string.Empty))" />
        </div>
        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@(EndDate?.ToString("yyyy-MM-dd"))" disabled="@IsCurrent" @onchange="e => UpdateField(() => EndDate = string.IsNullOrEmpty((string?)e.Value) ? null : DateTime.Parse((string)e.Value))" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent" @onchange="e => UpdateField(() => { IsCurrent = (bool)(e.Value ?? false); if (IsCurrent) EndDate = null; })" />
                Currently working here
            </label>
        </div>
    </div>
    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" value="@Description" @onchange="e => UpdateField(() => Description = (string?)e.Value ?? string.Empty)"></textarea>
    </div>
    @if (CanRemove)
    {
        <button type="button" class="btn-remove" @onclick="OnRemove">Remove</button>
    }
</div>

@code {
    [Parameter] public string Company { get; set; } = string.Empty;
    [Parameter] public string Title { get; set; } = string.Empty;
    [Parameter] public DateTime StartDate { get; set; } = DateTime.Today;
    [Parameter] public DateTime? EndDate { get; set; }
    [Parameter] public bool IsCurrent { get; set; }
    [Parameter] public string Description { get; set; } = string.Empty;
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryData> OnChanged { get; set; }

    private void UpdateField(Action update)
    {
        update();
        OnChanged.InvokeAsync(new WorkEntryData(Company, Title, StartDate, EndDate, IsCurrent, Description));
    }

    public record WorkEntryData(string Company, string Title, DateTime StartDate, DateTime? EndDate, bool IsCurrent, string Description);
}

