@using sv_39ebe269cbd34165bd1514589a11ff80.Services
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="application-container">
    <h1>Job Application</h1>

    <StepIndicator
        CurrentStep="currentStep"
        CompletedSteps="completedSteps"
        OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep
                FullName="@personalFullName"
                Email="@personalEmail"
                Phone="@personalPhone"
                Address="@personalAddress"
                OnNext="HandlePersonalNext" />
            break;

        case 1:
            <WorkHistoryStep
                Entries="workEntries"
                OnNext="HandleWorkNext"
                OnBack="() => GoToStep(0)" />
            break;

        case 2:
            <ReferencesStep
                References="references"
                OnNext="HandleReferencesNext"
                OnBack="() => GoToStep(1)" />
            break;

        case 3:
            <CoverLetterStep
                CoverLetter="@coverLetter"
                OnNext="HandleCoverLetterNext"
                OnBack="() => GoToStep(2)" />
            break;

        case 4:
            <ReviewStep
                Personal="@GetPersonalInfo()"
                WorkEntries="@GetWorkEntries()"
                References="@GetReferences()"
                CoverLetter="@coverLetter"
                OnEditStep="GoToStep"
                OnBack="() => GoToStep(3)"
                OnSubmit="HandleSubmit"
                IsSubmitting="isSubmitting"
                IsSubmitted="isSubmitted"
                ApplicationId="applicationId"
                ErrorMessage="@submitError" />
            break;
    }
</div>

@code {
    [Inject] private IApplicationService ApplicationService { get; set; } = default!;

    private int currentStep = 0;
    private HashSet<int> completedSteps = new();

    // Personal info state
    private string personalFullName = string.Empty;
    private string personalEmail = string.Empty;
    private string personalPhone = string.Empty;
    private string personalAddress = string.Empty;

    // Work history state
    private List<WorkHistoryStep.EntryModel> workEntries = new() { new() };

    // References state
    private List<ReferencesStep.ReferenceModel> references = new() { new(), new() };

    // Cover letter state
    private string coverLetter = string.Empty;

    // Submission state
    private bool isSubmitting;
    private bool isSubmitted;
    private int? applicationId;
    private string? submitError;

    private void GoToStep(int step)
    {
        currentStep = step;
    }

    private void HandlePersonalNext(PersonalInfoStep.PersonalInfoResult result)
    {
        personalFullName = result.FullName;
        personalEmail = result.Email;
        personalPhone = result.Phone;
        personalAddress = result.Address;
        completedSteps.Add(0);
        currentStep = 1;
    }

    private void HandleWorkNext(List<WorkHistoryStep.EntryModel> entries)
    {
        workEntries = entries;
        completedSteps.Add(1);
        currentStep = 2;
    }

    private void HandleReferencesNext(List<ReferencesStep.ReferenceModel> refs)
    {
        references = refs;
        completedSteps.Add(2);
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string text)
    {
        coverLetter = text;
        completedSteps.Add(3);
        currentStep = 4;
    }

    private async Task HandleSubmit()
    {
        isSubmitting = true;
        submitError = null;

        try
        {
            var application = new JobApplication(
                GetPersonalInfo(),
                new WorkHistory(GetWorkEntries()),
                GetReferences(),
                coverLetter
            );

            var id = await ApplicationService.SubmitApplicationAsync(application);
            applicationId = id;
            isSubmitted = true;
            completedSteps.Add(4);
        }
        catch (Exception ex)
        {
            submitError = $"Submission failed: {ex.Message}";
        }
        finally
        {
            isSubmitting = false;
        }
    }

    private PersonalInfo GetPersonalInfo() =>
        new(personalFullName, personalEmail, personalPhone, personalAddress);

    private List<WorkEntry> GetWorkEntries() =>
        workEntries.Select(e => new WorkEntry(e.Company, e.Title, e.StartDate, e.EndDate, e.Description)).ToList();

    private List<Reference> GetReferences() =>
        references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
}

