+    private HashSet<int> completedSteps = new();
+
+    // Personal info state
+    private string personalFullName = string.Empty;
+    private string personalEmail = string.Empty;
+    private string personalPhone = string.Empty;
+    private string personalAddress = string.Empty;
+
+    // Work history state
+    private List<WorkHistoryStep.EntryModel> workEntries = new() { new() };
+
+    // References state
+    private List<ReferencesStep.ReferenceModel> references = new() { new(), new() };
+
+    // Cover letter state
+    private string coverLetter = string.Empty;
+
+    // Submission state
+    private bool isSubmitting;
+    private bool isSubmitted;
+    private int? applicationId;
+    private string? submitError;
+
+    private void GoToStep(int step)
+    {
+        currentStep = step;
+    }
+
+    private void HandlePersonalNext(PersonalInfoStep.PersonalInfoResult result)
+    {
+        personalFullName = result.FullName;
+        personalEmail = result.Email;
+        personalPhone = result.Phone;
+        personalAddress = result.Address;
+        completedSteps.Add(0);
+        currentStep = 1;
+    }
+
+    private void HandleWorkNext(List<WorkHistoryStep.EntryModel> entries)
+    {
+        workEntries = entries;
+        completedSteps.Add(1);
+        currentStep = 2;
+    }
+
+    private void HandleReferencesNext(List<ReferencesStep.ReferenceModel> refs)
+    {
+        references = refs;
+        completedSteps.Add(2);
+        currentStep = 3;
+    }
+
+    private void HandleCoverLetterNext(string text)
+    {
+        coverLetter = text;
+        completedSteps.Add(3);
+        currentStep = 4;
+    }
+
+    private async Task HandleSubmit()
+    {
+        isSubmitting = true;
+        submitError = null;
+
+        try
+        {
+            var application = new JobApplication(
+                GetPersonalInfo(),
+                new WorkHistory(GetWorkEntries()),
+                GetReferences(),
+                coverLetter
+            );
